const greet = (name) => `Hello, ${name}!`;

function createOrder(item, quantity = 1, price = 0) {
  const total = quantity * price;
  return { item, quantity, price, total };
}

function sum(...numbers) {
  return numbers.reduce((acc, num) => acc + num, 0);
}

function repeat(fn, times) {
  for (let i = 0; i < times; i++) {
    fn(i);
  }
}

function demonstrateScope() {
  if (true) {
    let blockScoped = "I am block scoped";
    var functionScoped = "I am function scoped";
  }
  console.log(functionScoped); // Works - var leaks out of block
  // console.log(blockScoped); // Error - let is block scoped
}

repeat((i) => console.log(greet(`User ${i + 1}`)), 3);
console.log(createOrder("Widget", 5, 10));
console.log(sum(1, 2, 3, 4, 5));
